node - <<'NODE'
const fs = require('fs');
const path = require('path');

(async () => {
  let puppeteer;
  try {
    puppeteer = require('puppeteer');
  } catch (e) {
    console.error('Missing puppeteer. Add it to deps or vendor a renderer.');
    process.exit(1);
  }

  const htmlPath = path.resolve('/app/output/poster.html');
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-setuid-sandbox']
  });
  const page = await browser.newPage();
  await page.setViewport({ width: 2000, height: 2828, deviceScaleFactor: 2 });

  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle0', timeout: 60000 });
  // Wait until the infographic object exists
  await page.waitForFunction(() => !!window.__INFOGRAPHIC__, { timeout: 60000 });

  // small settle
  await page.waitForTimeout(500);

  const outPng = path.resolve('/app/output/final_poster.png');
  await page.screenshot({ path: outPng, fullPage: true });

  await browser.close();
  console.log('Wrote', outPng);
})();
